     }

     button {
       border: 0;
       border-radius: 12px;
       padding: 14px 18px;
       font: inherit;
       font-weight: 700;
       color: #f8fafc;
       background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
       cursor: pointer;
       transition: transform 140ms ease, box-shadow 140ms ease, filter 140ms ease;
       box-shadow: 0 14px 30px rgba(124, 58, 237, 0.28);
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.06);
     }

     button:active {
       transform: translateY(0);
     }

     .status {
       min-height: 1.25rem;
       margin: 0;
       font-size: 0.95rem;
       color: var(--success-text);
     }

     .status.success {
       padding: 10px 12px;
       border-radius: 10px;
       background: var(--success-bg);
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Confirm your consent</h1>
     <p class="intro">Please review and accept the terms of use before continuing.</p>

     <form id="consent-form">
       <div class="form-field">
         <div class="checkbox-row">
           <input id="terms" name="terms" type="checkbox" required>
           <label for="terms">I agree to the terms of use.</label>
         </div>
         <p class="helper-text">Required to continue with submission.</p>
       </div>

       <button type="submit">Submit</button>
       <p id="status" class="status" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const status = document.getElementById('status');

     form.addEventListener('submit', function (event) {
       event.preventDefault();

       if (!form.reportValidity()) {
         status.textContent = '';
         status.className = 'status';
         return;
       }

       status.textContent = 'Consent recorded. Your form is ready to proceed.';
       status.className = 'status success';
     });
